def transform(grid):
    # The bottom row encodes a cyclic color sequence in two segments. Copy
    # that sequence into the positions of the isolated marker cells, rotated
    # so each marker's color is the first element.
    h, w = len(grid), len(grid[0])
    base = [v for v in grid[-1] if v]
    out = [row[:] for row in grid]
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color:
                try:
                    i = base.index(color)
                except ValueError:
                    continue
                seq = base[i:] + base[:i]
                for j, v in enumerate(seq):
                    if c + j < w:
                        out[r][c + j] = v
    return out
