def transform(grid):
    h, w = len(grid), len(grid[0])
    runs=[]; run=[]; last=None
    for c, value in enumerate(grid[-1]):
        if value:
            if last is not None and c != last + 1:
                runs.append(run); run=[]
            run.append(value); last=c
        else:
            if run: runs.append(run); run=[]
            last=None
    if run: runs.append(run)
    out=[row[:] for row in grid]
    for r in range(h-1):
        for c, color in enumerate(grid[r]):
            if not color: continue
            key=next((seq for seq in runs if color in seq), None)
            if key is None: continue
            start=c-key.index(color)
            for j,v in enumerate(key):
                x=start+j
                if 0 <= x < w: out[r][x]=v
    return out
